<?php
require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_user();$pdo=db();$uid=(int)$_SESSION['user_id'];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';else{try{$action=$_POST['action']??'add';if($action==='delete')$pdo->prepare("DELETE FROM user_experience WHERE id=? AND user_id=?")->execute([(int)$_POST['id'],$uid]);else $pdo->prepare("INSERT INTO user_experience(user_id,organization,designation,employment_type,government_private,start_date,end_date,currently_working,total_experience,description) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$uid,trim($_POST['organization']),trim($_POST['designation']),trim($_POST['employment_type']),trim($_POST['government_private']),$_POST['start_date']?:null,$_POST['end_date']?:null,(int)($_POST['currently_working']??0),trim($_POST['total_experience']),trim($_POST['description'])]);flash('success','Experience updated.');redirect('experience.php');}catch(Throwable $e){$error='Could not save experience.';}}}
$st=$pdo->prepare("SELECT * FROM user_experience WHERE user_id=? ORDER BY start_date DESC,id DESC");$st->execute([$uid]);$rows=$st->fetchAll();$page_title='Experience';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?>
<div class="page-head"><div><h1>Experience</h1><p class="muted">Add experience where a recruitment notification requires it.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2>Add Experience</h2><form class="form-grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Organization<input name="organization"></label><label>Designation<input name="designation"></label><label>Employment Type<input name="employment_type"></label><label>Government / Private<input name="government_private"></label><label>Start Date<input type="date" name="start_date"></label><label>End Date<input type="date" name="end_date"></label><label>Currently Working<select name="currently_working"><option value="0">No</option><option value="1">Yes</option></select></label><label>Total Experience<input name="total_experience" placeholder="e.g. 2 years 4 months"></label><label class="span-2">Description<textarea name="description"></textarea></label><div class="form-actions"><button class="btn btn-primary">Add Experience</button></div></form></div>
<div class="job-list"><?php foreach($rows as $r):?><div class="card"><h3><?=e($r['designation'])?></h3><p><?=e($r['organization'])?> · <?=e($r['government_private'])?></p><p><?=e($r['total_experience'])?></p><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-small">Delete</button></form></div><?php endforeach;if(!$rows):?><div class="empty">No experience records added.</div><?php endif;?></div><?php require '../includes/footer.php';?>